-- Richmond: dated sessions read from the owners' own calendar pages (MahjongRVA, The Lucky Sparrow) by the new calendar-widget reader (checked 2026-10-12).
INSERT INTO "Event" ("id", "name", "slug", "eventDate", "startTime", "endTime", "venue", "cityId", "clubId", "instructorId", "eventType", "beginnerFriendly", "price", "registrationUrl", "sourceUrl", "lastVerifiedAt", "status")
VALUES ('event_richmond-open-play-bar-west-20261108', 'Open Play @ Bar West!', 'richmond-open-play-bar-west-20261108', '2026-11-08 00:00:00', '15:00', NULL, 'Bar West', (SELECT id FROM City WHERE name = 'Richmond' AND state = 'VA'), NULL, (SELECT id FROM Instructor WHERE name = 'The Lucky Sparrow / Emily Cox' AND cityId = (SELECT id FROM City WHERE name = 'Richmond' AND state = 'VA')), 'OPEN_PLAY', 0, 25, 'https://www.theluckysparrow.com/events', 'https://www.theluckysparrow.com/events', '2026-10-12', 'ACTIVE')
ON CONFLICT("slug") DO UPDATE SET "name" = excluded."name", "eventDate" = excluded."eventDate", "startTime" = excluded."startTime", "endTime" = excluded."endTime", "venue" = excluded."venue", "cityId" = excluded."cityId", "clubId" = excluded."clubId", "instructorId" = excluded."instructorId", "eventType" = excluded."eventType", "beginnerFriendly" = excluded."beginnerFriendly", "price" = excluded."price", "registrationUrl" = excluded."registrationUrl", "sourceUrl" = excluded."sourceUrl", "lastVerifiedAt" = excluded."lastVerifiedAt", "status" = excluded."status", "updatedAt" = CURRENT_TIMESTAMP;

